      async function submitAiCredential(event) {
        event.preventDefault();
        const providerId = $('#ai-credential-provider')?.value || '';
        const value = $('#ai-credential-value')?.value || '';
        const mfaCode = $('#ai-credential-mfa')?.value?.trim() || '';
        const submit = $('#ai-credential-submit'); const notice = $('#ai-credential-notice');
        const show = (message, state = '') => { notice.textContent = message; notice.dataset.state = state; };
        if (!value) { show('کلید API را وارد کنید.', 'error'); return; }
        submit.disabled = true; show('در حال رمزنگاری و ثبت در Secret Store محیط Test…');
        const save = () => requestJson('/api/ai/credentials', { providerId, value });
        try {
          let result;
          try { result = await save(); }
          catch (error) {
            if (error.code !== 'STEP_UP_REQUIRED' || !mfaCode) throw error;
            await requestJson('/api/identity/step-up', { mfaCode });
            result = await save();
          }
          $('#ai-credential-value').value = ''; $('#ai-credential-mfa').value = '';
          show('کلید ' + providerId + ' با موفقیت در Secret Store رمزنگاری شد. مقدار آن نمایش داده نمی‌شود؛ اکنون «تست آماده‌بودن» را بزنید.', 'success');
          await refresh('وضعیت Secretهای AI به‌روز شد.');
        } catch (error) {
          show(error.code === 'STEP_UP_REQUIRED' ? 'نشست شما قدیمی است؛ کد ۶ رقمی MFA را وارد و دوباره ذخیره کنید.' : (error.message || 'ثبت کلید انجام نشد.'), 'error');
        } finally { submit.disabled = false; }
      }
