      function renderBenchmarkHistory(data) { const runs = data?.benchmark?.recent || []; const container = $('#benchmark-history'); container.replaceChildren(...(runs.length ? runs.map(run => { const item = document.createElement('div'); item.className = 'activity-row'; const recordedAt = run.recordedAt ? new Date(run.recordedAt).toLocaleString('fa-IR') : 'زمان ثبت نشده'; const metrics = run.metrics || {}; item.append(text('strong', run.benchmarkId || 'بدون شناسه'), text('span', (run.providerId || 'provider') + ' / ' + (run.modelId || 'model') + ' · schema ' + (metrics.schemaPassRate ?? '—') + ' · safety ' + (metrics.safetyPassRate ?? '—') + ' · ' + recordedAt + ' · digest ' + String(run.digest || '').slice(0, 12))); return item; }) : [text('p', 'هنوز Benchmark synthetic ثبت نشده است.', 'muted')])); }
      function render(data) {
        currentData = data; const counts = data.ai?.counts || {}; const metrics = [['تیم‌های سازمان', data.organization?.teamCount || 0, 'teams.contracts'], ['Roleهای AI', data.ai?.roles?.length || 0, 'ai.rolesActivity'], ['Invocationها', counts.invocations || 0, 'ai.invocations'], ['درخواست‌های ثبت‌شده', data.requests?.total || 0, 'command.statusOverview']]; $('#metrics').replaceChildren(...metrics.map(([label, value, key]) => { const item = document.createElement('div'); item.className = 'metric'; item.append(text('strong', value), featureText('span', label, '', key)); return item; }));
        const stop = Boolean(data.governance?.globalStop); const overall = badge(stop ? 'توقف اضطراری فعال' : 'مرز مشاهده‌ای سالم', stop ? 'blocked' : 'good'); overall.id = 'overall'; $('#overall').replaceWith(overall);
        $('#status-grid').replaceChildren(...(data.focus || []).map(item => { const card = document.createElement('article'); card.className = 'focus-card ' + (item.tone === 'blocked' ? 'blocked' : item.tone === 'warn' ? 'warn' : ''); card.append(featureText('h3', item.title, '', 'command.currentGates'), badge(item.status, item.tone), text('p', item.detail), text('small', 'بعدی: ' + item.next)); return card; }));
        renderProjectSettings(data); renderPlanning(data); renderRoadmap(data); renderProjectionStatus(data); renderProjectMemory(data); renderRoleChips(data); renderAiConnections(data); renderAiAssignmentMatrix(data); renderAiCatalog(data); renderConfigFields(); const activity = data.ai?.activity || {}; const activityRows = [['Invocation', (activity.invocations || []).length, 'ai.invocations'], ['Evaluation', (activity.evaluations || []).length, 'ai.evaluations'], ['Decision', (activity.decisions || []).length, 'ai.decisions']]; $('#ai-activity').replaceChildren(...activityRows.map(([label, value, infoKey]) => { const item = document.createElement('div'); item.className = 'activity-row'; item.append(featureText('strong', label, '', infoKey), text('span', value + ' مورد اخیر')); return item; })); $('#provider-note').textContent = 'حالت Provider: ' + (data.ai?.providerMode || 'ثبت نشده') + ' · ' + (data.ai?.liveStatus || 'وضعیت ثبت نشده'); $('#benchmark-note').textContent = 'Benchmark: ' + (data.benchmark?.mode || 'synthetic-deterministic') + ' · ' + (data.benchmark?.decisionBoundary || 'advisory-only'); const policies = data.ai?.defaultRolePolicies || []; $('#ai-policy-list').replaceChildren(...(policies.length ? policies.map(policy => { const item = document.createElement('div'); item.className = 'activity-row'; item.append(text('strong', policy.role), text('span', policy.providerId + ' / ' + policy.modelId + ' · ' + policy.toolPolicy + ' · v' + policy.policyVersion)); return item; }) : [text('p', 'Policy پیش‌فرض هنوز ثبت نشده.', 'muted')])); const advisor = data.advisor || {}; const latestAdvisor = advisor.latest; $('#advisor-note').textContent = latestAdvisor ? 'مشاور سازمان: ' + latestAdvisor.state + ' · پیشنهاد: ' + (latestAdvisor.recommendation?.optionId || 'ثبت نشده') + ' · خروجی فقط advisory است.' : 'مشاور سازمان هنوز ارزیابی نشده است.';
        renderTeams(); renderGuide(data); renderBenchmarkHistory(data);
        const timeline = data.timeline || []; $('#timeline').replaceChildren(...(timeline.length ? timeline : [{ type: 'timeline.empty', kind: 'persistence', aggregateType: '-', aggregateId: '-', occurredAt: null }]).map(event => { const item = document.createElement('div'); item.className = 'timeline-item'; item.append(text('strong', event.type), text('span', event.aggregateType + ' / ' + event.aggregateId + ' · ' + event.kind), text('small', event.occurredAt ? new Date(event.occurredAt).toLocaleString('fa-IR') : 'هنوز eventی ثبت نشده')); return item; }));
        const reviews = data.performance?.reviews || []; $('#reviews').replaceChildren(...(reviews.length ? reviews : [{ reviewId: '—', period: 'هنوز ارزیابی ثبت نشده', average: null, band: 'neutral', teamCount: 0 }]).map(review => { const item = document.createElement('div'); item.className = 'review'; const info = document.createElement('div'); info.append(text('strong', review.reviewId), text('small', review.period + ' · پوشش تیم: ' + review.teamCount)); item.append(info, badge(review.average === null ? 'بدون داده' : review.average + '/100 · ' + review.band, review.band === 'strong' ? 'good' : review.band === 'intervention' ? 'blocked' : review.band === 'watch' ? 'warn' : '')); return item; }));
        $('#next-steps').replaceChildren(...(data.nextSteps || []).map((step, index) => { const item = document.createElement('div'); item.className = 'next-step'; item.append(text('b', String(index + 1)), text('span', step)); return item; })); const openStatuses = Object.entries(data.requests?.byStatus || {}).map(([key, value]) => key + ': ' + value).join(' · '); $('#updated').textContent = 'آخرین خواندن: ' + new Date(data.generatedAt).toLocaleString('fa-IR') + (openStatuses ? ' · وضعیت درخواست‌ها: ' + openStatuses : ''); $('#access-note').textContent = 'دسترسی: فقط همین میزبان · ' + (data.access?.path || '/backoffice');
      }
      async function refresh(message) { $('#notice').textContent = 'در حال به‌روزرسانی…'; try { render(await safeFetch()); setNotice(message || 'وضعیت پنل به‌روز شد.'); } catch (error) { if (currentData) { setNotice(message || 'اطلاعات پنل نمایش داده شد؛ برای تازه‌سازی کامل، صفحه را دوباره بارگذاری کن.'); } else setNotice(error.message); } }
      function downloadReport() { if (!currentData) { setNotice('ابتدا صبر کن تا وضعیت پنل خوانده شود.'); return; } const blob = new Blob([JSON.stringify({ reportVersion: '1.0', exportedAt: new Date().toISOString(), backoffice: currentData }, null, 2)], { type: 'application/json;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'hero-backoffice-report.json'; link.click(); URL.revokeObjectURL(url); setNotice('گزارش امن آماده شد؛ متن درخواست و اطلاعات حساس در آن نیست.'); }
      function openPrinciplesEditor(team) { editingTeam = team; $('#dialog-team-name').textContent = team.name + ' · نسخهٔ قرارداد ' + (team.version ?? 0); $('#principles-input').value = (team.contract?.principles || []).join('\\n'); $('#dialog-notice').textContent = ''; const dialog = $('#principles-dialog'); if (typeof dialog.showModal === 'function') dialog.showModal(); else setNotice('مرورگر این ویرایشگر را پشتیبانی نمی‌کند.'); }
      function closePrinciplesEditor() { const dialog = $('#principles-dialog'); if (dialog.open) dialog.close(); editingTeam = null; }
      async function savePrinciples(event) { event.preventDefault(); if (!editingTeam) return; const token = ($('#owner-token').value || '').trim(); if (!token) { $('#dialog-notice').textContent = 'برای ذخیره، توکن مالک یا Admin را وارد کنید.'; return; } const principles = $('#principles-input').value.split('\\n').map(value => value.trim()).filter(Boolean); if (!principles.length) { $('#dialog-notice').textContent = 'حداقل یک اصل وارد کنید.'; return; } const save = $('#dialog-save'); const teamName = editingTeam.name; save.disabled = true; $('#dialog-notice').textContent = 'در حال ثبت نسخه…'; try { await requestJson('/api/teams/' + encodeURIComponent(editingTeam.teamId) + '/principles', { principles, expectedVersion: editingTeam.version, idempotencyKey: 'backoffice-principles-' + editingTeam.teamId + '-' + Date.now() }, token); closePrinciplesEditor(); await refresh('اصول ' + teamName + ' ذخیره شد؛ تأیید مالک دوباره لازم است.'); } catch (error) { $('#dialog-notice').textContent = error.message; } finally { save.disabled = false; } }
      async function reviewPrinciples(team) { const token = ($('#owner-token').value || '').trim(); if (!token) { setNotice('برای تأیید اصول، توکن مالک را وارد کنید.'); return; } if (token.startsWith('hero-admin-session.')) { setNotice('تأیید نهایی اصول فقط با توکن مالک پروژه انجام می‌شود.'); return; } try { await requestJson('/api/teams/' + encodeURIComponent(team.teamId) + '/review', { target: 'principles', decision: 'approved', expectedVersion: team.version, idempotencyKey: 'backoffice-approve-principles-' + team.teamId + '-' + Date.now() }, token); await refresh('اصول ' + team.name + ' تأیید شد.'); } catch (error) { setNotice(error.message); } }
      const aiScopeOption = new Option('Scope پروژهٔ AI', 'project-scope'); if ($('#config-kind') && !Array.from($('#config-kind').options).some(option => option.value === 'project-scope')) $('#config-kind').append(aiScopeOption);
